import {randomBytes} from 'node:crypto';import {createCiteStore} from './cite-store.mjs';
import {initializeCity,cityPublicView,cityFamilyView} from '../cite/city.ts';
/** The seed is generated by trusted server code; no client seed or ad-hoc crisis endpoint. */
export function createCiteCityService(adapter,{newSeed=()=>randomBytes(32).toString('hex'),...options}={}){
 const store=createCiteStore(adapter,options);
 const operate=(header,scope,permission,fn)=>store(header,scope,permission,record=>{if(!record.councils)throw Object.assign(Error('Councils not initialized'),{status:409});const game={economy:record.state,councils:record.councils,...(record.city?{city:record.city}:{})};const next=fn(game);return {record:next.game===game?record:{...record,city:next.game.city},value:next.value};});
 return {
  initialize:(header,scope)=>operate(header,scope,'manager',game=>{const next=game.city?game:initializeCity(game,scope,newSeed());return {game:next,value:cityPublicView(next,scope)};}),
  public:(header,scope)=>operate(header,scope,'viewer',game=>({game,value:cityPublicView(game,scope)})),
  family:(header,scope)=>operate(header,scope,'member',game=>({game,value:cityFamilyView(game,scope)}))
 };
}
